    ]
  }
}
```

**前端示例**（侧栏组件，两个页面复用）：

```tsx
// src/components/HotPosts.tsx
import { useEffect, useState } from 'react';
import { api } from '../lib/api';
import type { ArticleCard } from '../lib/types';

export function HotPosts() {
  const [list, setList] = useState<ArticleCard[]>([]);
  useEffect(() => {
